import{_ as s,l as i,o as e,c as n,v as t,p as l,x as o,d as c,i as d,S as A}from"./chunks/framework.InCnrqk-.js";const u=JSON.parse('{"title":"缓存别名","description":"","frontmatter":{"title":"缓存别名","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/cache-aliasing.md","filePath":"cs/cache-aliasing.md","lastUpdated":1789023840000}'),h={name:"cs/cache-aliasing.md"};function p(m,a,_,B,E,P){const r=i("Mermaid");return e(),n("div",null,[a[1]||(a[1]=t('<h1 id="缓存别名" tabindex="-1">缓存别名 <a class="header-anchor" href="#缓存别名" aria-label="Permalink to &quot;缓存别名&quot;">​</a></h1><div class="epigraph"><p>同一物理行若能被两个虚拟地址索引到不同的组，L1 里就会出现两份副本；写其中一份，另一份变成静默的陈旧数据。</p><footer>—— 据 Hennessy and Patterson, CA:AQA 整理</footer></div><p><a href="/cs/vipt-cache">上一课</a> 要求 VIPT 的索引落在页内，正是为了堵住同义（synonym）。实践中人们仍想做更大的 L1，索引会借到 VPN 位。本课不重讲 TLB 并行。缺口是<strong>别名：同义与同名（homonym），以及硬件或软件如何保证最多一份有效副本。</strong></p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>同义：两个 VA 映射到同一 PA（共享页、<code>mmap</code> 两次）。若索引用了 VPN 位，两份 VA 进不同组，L1 变成「两个 cache 行对应一块内存」。单核写回已经乱；再叠加 <a href="/cs/mesi-protocol">MESI</a> 更无法定义哪份是 M。同名：同一 VA 在不同 ASID 下指不同 PA，VIVT 会把旧进程的行当成新进程的命中。缺口不是替换策略，而是<strong>检测或避免第二份副本。</strong></p><p><span class="marginnote">页着色：OS 分配物理页时让 PA 的某些位与 VA 一致，从而「越页」的索引位实际上在同义之间相同。这是软件契约，硬件仍可加探测器。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>避免：限制 L1 使索引 ⊆ 页内（上一课）。页着色：OS 保证同义的 VA 在索引位上一致。硬件：填入时按 PA 查「是否已在另一组」，有则先无效或搬移。VIVT 用 ASID 标签，切换不必全冲，但同义仍要处理。</p>',8)),(e(),l(A,null,{default:o(()=>[d(r,{id:"mermaid-22",class:"mermaid",graph:"flowchart%20TD%0A%20%20VA1%5B%22VA1%20%E7%B4%A2%E5%BC%95%E7%BB%84%20A%22%5D%20--%3E%20P%5B%22%E5%90%8C%E4%B8%80%20PA%22%5D%0A%20%20VA2%5B%22VA2%20%E7%B4%A2%E5%BC%95%E7%BB%84%20B%22%5D%20--%3E%20P%0A%20%20P%20--%3E%20HAZ%5B%22%E4%B8%A4%E4%BB%BD%20L1%20%E5%89%AF%E6%9C%AC%22%5D%0A%20%20HAZ%20--%3E%20FIX%5B%22%E7%9D%80%E8%89%B2%20%2F%20%E6%8E%A2%E6%B5%8B%E4%BD%9C%E5%BA%9F%20%2F%20%E9%99%90%E5%88%B6%E7%B4%A2%E5%BC%95%22%5D%0A"})]),fallback:o(()=>[...a[0]||(a[0]=[c(" Loading... ",-1)])]),_:1})),a[2]||(a[2]=t('<h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>别名是正确性问题，不是性能调优。调试器里「变量改了但读到旧值」可以来自这里。I-cache 与 D-cache 对同一物理页的别名（SMC）是另一条：指令行必须在 store 后无效，与 uop cache 的 SMC 纪律相同。</p><p>大页让页内位移变长，VIPT 可索引更大 L1，同义窗口变小——后课大页会再提，本课只记「页大小是别名几何的一部分」。</p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不把 GPU 的纹理 cache 别名当主干。也不把写合并缓冲的部分行写成别名解决方案。路预测下一课：那是在「已经只有一份、多路比较贵」时猜哪一路，不是修副本。</p><p>后课默认：L1 要么几何上杜绝同义，要么 OS/硬件显式消第二份。多路并行比较的功耗，用路预测来砍。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>同义别名产生多份物理行副本，必须着色、探测或限制索引。</li><li>同名靠物理标签或 ASID，不能只信 VA。</li><li>多路都读但只启用一路，是下一课路预测。</li><li>出处：Hennessy and Patterson, <em>CA:AQA</em>。</li></ul>',8))])}const f=s(h,[["render",p]]);export{u as __pageData,f as default};
